import"./alert_indicator.js";import{CustomElement}from"chrome://resources/js/custom_element.js";import{AlertIndicatorElement}from"./alert_indicator.js";import{getTemplate}from"./alert_indicators.html.js";import{TabAlertState}from"./tabs.mojom-webui.js";export class AlertIndicatorsElement extends CustomElement{static get template(){return getTemplate()}constructor(){super();this.containerEl_=this.$("#container");const audioIndicator=new AlertIndicatorElement;const recordingIndicator=new AlertIndicatorElement;this.alertIndicators_=new Map([[TabAlertState.kMediaRecording,recordingIndicator],[TabAlertState.kTabCapturing,new AlertIndicatorElement],[TabAlertState.kAudioPlaying,audioIndicator],[TabAlertState.kAudioMuting,audioIndicator],[TabAlertState.kBluetoothConnected,new AlertIndicatorElement],[TabAlertState.kUsbConnected,new AlertIndicatorElement],[TabAlertState.kHidConnected,new AlertIndicatorElement],[TabAlertState.kSerialConnected,new AlertIndicatorElement],[TabAlertState.kPipPlaying,new AlertIndicatorElement],[TabAlertState.kDesktopCapturing,recordingIndicator],[TabAlertState.kVrPresentingInHeadset,new AlertIndicatorElement]])}updateAlertStates(alertStates){const alertIndicators=alertStates.map((alertState=>this.alertIndicators_.get(alertState)));let alertIndicatorCount=0;for(const[index,alertState]of alertStates.entries()){const alertIndicator=alertIndicators[index];if(!alertIndicator){continue}if(alertIndicators.indexOf(alertIndicator)<index){continue}alertIndicator.alertState=alertState;this.containerEl_.insertBefore(alertIndicator,this.containerEl_.children[alertIndicatorCount]);alertIndicator.show();alertIndicatorCount++}const animationPromises=Array.from(this.containerEl_.children).slice(alertIndicatorCount).map((indicator=>indicator.hide()));return Promise.all(animationPromises).then((()=>this.containerEl_.childElementCount),(()=>-1))}}customElements.define("tabstrip-alert-indicators",AlertIndicatorsElement);